import os
from pathlib import Path

import pytest


def count_readable(names: list[str]) -> int:
    """Count the names that refer to a readable regular file inside `notes`.

    `notes` is a directory relative to the current working directory. Each
    name is resolved relative to `notes`, and subdirectory names such as
    "sub/b.txt" are valid. A name counts once per occurrence in `names`
    (duplicates are counted each time). Missing files, directories,
    unreadable files, empty names and names containing NUL bytes do not
    count. Names are untrusted: absolute paths, ".." traversal, and symlinks
    that lead outside `notes` never count, and no file outside `notes` is
    ever opened.
    """
    root = os.path.realpath("notes")
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    total = 0
    for name in names:
        if not name or "\x00" in name or os.path.isabs(name):
            continue
        resolved = os.path.realpath(os.path.join(root, name))
        try:
            if os.path.commonpath([root, resolved]) != root:
                continue
        except ValueError:
            continue
        if resolved == root or not os.path.isfile(resolved):
            continue
        try:
            fd = os.open(resolved, flags)
        except OSError:
            continue
        os.close(fd)
        total += 1
    return total


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha")
    (notes / "sub" / "b.txt").write_text("beta")
    (notes / "empty.txt").write_text("")
    (tmp_path / "secret.txt").write_text("top secret")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_empty_list(workdir: Path) -> None:
    assert count_readable([]) == 0


def test_plain_and_subdirectory_files(workdir: Path) -> None:
    assert count_readable(["a.txt", "sub/b.txt"]) == 2


def test_empty_file_is_readable(workdir: Path) -> None:
    assert count_readable(["empty.txt"]) == 1


def test_missing_files_not_counted(workdir: Path) -> None:
    assert count_readable(["nope.txt", "sub/nope.txt", "nodir/x.txt"]) == 0


def test_mixed(workdir: Path) -> None:
    assert count_readable(["a.txt", "missing.txt", "sub/b.txt"]) == 2


def test_duplicates_counted_each_time(workdir: Path) -> None:
    assert count_readable(["a.txt", "a.txt"]) == 2


def test_directories_not_counted(workdir: Path) -> None:
    assert count_readable(["sub", "sub/", "."]) == 0


def test_empty_name(workdir: Path) -> None:
    assert count_readable([""]) == 0


def test_parent_traversal_rejected(workdir: Path) -> None:
    assert count_readable(["../secret.txt"]) == 0
    assert count_readable(["sub/../../secret.txt"]) == 0
    assert count_readable(["../notes/../secret.txt"]) == 0
    assert count_readable(["..", "../"]) == 0


def test_deep_traversal_rejected(workdir: Path) -> None:
    assert count_readable(["../" * 10 + "etc/passwd"]) == 0


def test_absolute_path_rejected(workdir: Path) -> None:
    secret = str(workdir / "secret.txt")
    inside = str(workdir / "notes" / "a.txt")
    assert count_readable([secret]) == 0
    assert count_readable([inside]) == 0
    assert count_readable(["/etc/passwd"]) == 0


def test_nul_byte_name(workdir: Path) -> None:
    assert count_readable(["a.txt\x00../secret.txt", "\x00"]) == 0


def test_symlink_to_outside_file_rejected(workdir: Path) -> None:
    link = workdir / "notes" / "link.txt"
    try:
        link.symlink_to(workdir / "secret.txt")
    except OSError:
        pytest.skip("symlinks unavailable")
    assert count_readable(["link.txt"]) == 0


def test_symlinked_dir_to_outside_rejected(workdir: Path) -> None:
    outside = workdir / "outside"
    outside.mkdir()
    (outside / "x.txt").write_text("x")
    link = workdir / "notes" / "linkdir"
    try:
        link.symlink_to(outside, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks unavailable")
    assert count_readable(["linkdir/x.txt"]) == 0


def test_unreadable_file_not_counted(workdir: Path) -> None:
    if hasattr(os, "geteuid") and os.geteuid() == 0:
        pytest.skip("root can read anything")
    f = workdir / "notes" / "locked.txt"
    f.write_text("x")
    f.chmod(0)
    try:
        assert count_readable(["locked.txt", "a.txt"]) == 1
    finally:
        f.chmod(0o644)


def test_missing_notes_directory(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    (tmp_path / "secret.txt").write_text("s")
    assert count_readable(["a.txt", "../secret.txt"]) == 0

